def source_link(s):
    path, line = s.rsplit(':',1)
    target = root/'GlassTable/Sources'/path
    if not target.exists():
        hits=list((root/'GlassTable/Sources').rglob(Path(path).name))
        if hits: target=hits[0]
    return f'<a href="{esc(target.as_uri())}">{esc(target.relative_to(root))}:{esc(line)}</a>'

